ldSurface":null,"isNew":true,"lexemeId":"d8d6fd7a-c5fd-53b6-a2f7-a11a3fa9b5db","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:3554-3563:d6780309fc88a13e32ccdfde0de40d89d7c4783d32bb4c2eade239de13b12010","target":true},{"term":"security patrols","partOfSpeech":"noun phrase","definitionEn":"people who regularly check an area for safety and security","translationUz":"qo‘riqlash patrullari","start":3795,"end":3811,"surface":"Security patrols","id":"1e105399-26ee-5ee9-b1b8-687402c6d43b","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"edf378cf-01b7-5705-a2e3-4e6cff7d6d6a","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:3795-3811:aa8b715285317ee1d28d3548b53873ddfd6394e3c7a6bc6bdb47347e27257606","target":true},{"term":"act as a deterrent","partOfSpeech":"verb phrase","definitionEn":"discourage people from committing an offence","translationUz":"qoidabuzarlikdan qaytaruvchi vosita bo‘lmoq","start":3822,"end":3840,"surface":"act as a deterrent","id":"f9dfcfb0-9078-50af-9b98-383c25e1ddde","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"2515fb39-c358-536c-a17e-95ec356db6d4","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:3822-3840:e80816addf856a71cb6a29627011946389f4ea38ab58ced531a6f9e3eb623a63","target":true},{"term":"physical barrier","partOfSpeech":"noun phrase","definitionEn":"a structure that prevents entry","translationUz":"kirishga to‘sqinlik qiluvchi jismoniy to‘siq","start":3936,"end":3952,"surface":"physical barrier","id":"08d72414-1ad4-57a8-b7dd-7fe26be72c80","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"c7c44ae4-c43b-5205-9ddb-507def5815c4","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:3936-3952:b2d7a8183d2be003e1b66f53c89cd00fcf2c7d8954b9b3f27b125f7834036a78","target":true},{"term":"unauthorized access","partOfSpeech":"noun phrase","definitionEn":"entry without permission","translationUz":"ruxsatsiz kirish","start":4026,"end":4045,"surface":"unauthorized access","id":"bf6ce133-90c1-5edb-85ac-c062ab601c9f","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"140dd0db-086f-571c-ad74-93ca1c4aca47","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:4026-4045:095ef89c3dfe81d5ecd43c50277ca79345f9f74f70677442bf5e83369ae25b21","target":true},{"term":"consideration has to be given to","partOfSpeech":"verb phrase","definitionEn":"attention must be paid to","translationUz":"…ni hisobga olish kerak","start":4077,"end":4109,"surface":"consideration has to be given to","id":"7fc0b52d-1c17-5ef2-a309-4452bf730520","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"517cdd50-5c0e-5788-9c9f-5b3d58d243b1","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:4077-4109:9ac68dde7e20868f830897daffdb30e5747e6df4abbd5b40eaed6865b66d5f8d","target":true},{"term":"under these circumstances","partOfSpeech":"adverbial phrase","definitionEn":"in the situation just described","translationUz":"bunday sharoitda","start":4489,"end":4514,"surface":"Under these circumstances","id":"d4222065-cfd0-58f7-938e-b6d977581c10","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"ca2568fb-707b-5028-a380-1a930ef66bc3","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:4489-4514:53d423be93be5794b01d59e9bed073ec141d001d33c5a0c7519db8b378920d1a","target":true},{"term":"thin veneer","partOfSpeech":"noun phrase","definitionEn":"a very thin layer covering the surface","translationUz":"yupqa ustki qoplama","start":4842,"end":4853,"surface":"thin veneer","id":"bf354f3e-2661-55e6-b439-e415968d0417","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"3e7b2014-ba40-59c4-a7b6-febd0ff385c9","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:4842-4853:1cd94ba150d58e6ae8ccbd40f1d845ffdf86212b4c3c40f40cf45e55af807786","target":true},{"term":"depending on","partOfSpeech":"prepositional phrase","definitionEn":"according to the condition or choice specified","translationUz":"…ga qarab","start":5080,"end":5092,"surface":"Depending on","id":"81702afd-1c79-56c9-a484-65051dce1769","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"6c54f9e9-c008-582b-806f-91066fedd2de","senseKey":"reading:818290cd-9f13-4f06-b453-6e1012552c63:b317315fac4ce20b44400dbc74c1d831db621c727424da76934515af9cfa2acb:5080-5092:c9a490c5a55b9d989981e5d4ebc3181b350ff9820643027aa8d0887516cfd5b3","target":true}]}]}'::jsonb;
  passage jsonb;
  item jsonb;
  source text;
  current_row public.lexical_occurrences%ROWTYPE;
  before_users text;
  after_users text;
  before_lexemes text;
  after_lexemes text;
  planned_ids uuid[];
BEGIN
  IF jsonb_array_length(manifest->'passages') <> 2 OR
     (SELECT count(DISTINCT p->>'id') FROM jsonb_array_elements(manifest->'passages') p) <> 2 THEN
    RAISE EXCEPTION 'reading_pair_requires_two_passages';
  END IF;
  SELECT array_agg((e->>'lexemeId')::uuid) INTO planned_ids
    FROM jsonb_array_elements(manifest->'passages') p,
         jsonb_array_elements(p->'entries') e;
  SELECT md5(coalesce(string_agg(to_jsonb(v)::text,'' ORDER BY id),''))
    INTO before_users FROM public.user_vocabulary v;
  SELECT md5(coalesce(string_agg(to_jsonb(l)::text,'' ORDER BY id),''))
    INTO before_lexemes FROM public.lexemes l WHERE NOT (id=ANY(planned_ids));
  -- Lock both canonical bodies in stable order before changing either passage.
  PERFORM id FROM public.reading_passages WHERE id IN
    (SELECT (p->>'id')::uuid FROM jsonb_array_elements(manifest->'passages') p)
    ORDER BY id FOR SHARE;
  FOR passage IN SELECT value FROM jsonb_array_elements(manifest->'passages') LOOP
    SELECT body_text INTO STRICT source FROM public.reading_passages WHERE id=(passage->>'id')::uuid;
    IF encode(sha256(convert_to(source,'UTF8')),'hex') <> passage->>'sourceSha256' THEN
      RAISE EXCEPTION 'reading_pair_source_changed: %',passage->>'id';
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(passage->'entries') LOOP
      IF (item->>'start')::int < 0 OR (item->>'end')::int <= (item->>'start')::int OR
         substring(source FROM (item->>'start')::int+1 FOR (item->>'end')::int-(item->>'start')::int)
           IS DISTINCT FROM item->>'surface' THEN
        RAISE EXCEPTION 'reading_pair_span_changed: %',item->>'id';
      END IF;
      INSERT INTO public.lexemes(id,term,part_of_speech,definition_en,translation_uz,sense_key,
          provenance,verification_status,import_batch)
        VALUES((item->>'lexemeId')::uuid,item->>'term',item->>'partOfSpeech',item->>'definitionEn',
          item->>'translationUz',item->>'senseKey','authored','verified',manifest->>'release')
        ON CONFLICT(id) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM public.lexemes WHERE id=(item->>'lexemeId')::uuid
          AND term=item->>'term' AND part_of_speech=item->>'partOfSpeech'
          AND definition_en=item->>'definitionEn' AND translation_uz=item->>'translationUz'
          AND sense_key=item->>'senseKey') THEN
        RAISE EXCEPTION 'reading_pair_meaning_collision: %',item->>'lexemeId';
      END IF;
      SELECT * INTO current_row FROM public.lexical_occurrences WHERE id=(item->>'id')::uuid FOR UPDATE;
      IF FOUND THEN
        IF current_row.source_type <> 'reading' OR current_row.passage_id <> (passage->>'id')::uuid
           OR current_row.start_char <> (item->>'start')::int OR current_row.end_char <> (item->>'end')::int THEN
          RAISE EXCEPTION 'reading_pair_identity_changed: %',item->>'id';
        END IF;
        IF current_row.lexeme_id=(item->>'lexemeId')::uuid AND current_row.surface_form=item->>'surface'
           AND current_row.is_target_vocabulary=(item->>'target')::boolean
           AND current_row.resolution_status='resolved' AND current_row.resolution_source='authored-context' THEN
          CONTINUE;
        END IF;
        IF (item->>'isNew')::boolean OR current_row.lexeme_id IS DISTINCT FROM (item->>'oldLexemeId')::uuid
           OR current_row.surface_form IS DISTINCT FROM item->>'oldSurface' THEN
          RAISE EXCEPTION 'reading_pair_previous_binding_changed: %',item->>'id';
        END IF;
        UPDATE public.lexical_occurrences SET lexeme_id=(item->>'lexemeId')::uuid,
          lexical_unit_id=NULL,surface_form=item->>'surface',
          is_target_vocabulary=(item->>'target')::boolean,
          resolution_status='resolved',resolution_source='authored-context' WHERE id=current_row.id;
      ELSE
        IF NOT (item->>'isNew')::boolean THEN
          RAISE EXCEPTION 'reading_pair_existing_id_missing: %',item->>'id';
        END IF;
        INSERT INTO public.lexical_occurrences(id,passage_id,lexeme_id,source_type,start_char,end_char,
            surface_form,occurrence_type,is_target_vocabulary,resolution_status,resolution_source)
          VALUES((item->>'id')::uuid,(passage->>'id')::uuid,(item->>'lexemeId')::uuid,'reading',
            (item->>'start')::int,(item->>'end')::int,item->>'surface',
            CASE WHEN item->>'surface' ~ '\s' THEN 'phrase' ELSE 'word' END,
            (item->>'target')::boolean,'resolved','authored-context');
      END IF;
    END LOOP;
  END LOOP;
  SELECT md5(coalesce(string_agg(to_jsonb(v)::text,'' ORDER BY id),''))
    INTO after_users FROM public.user_vocabulary v;
  SELECT md5(coalesce(string_agg(to_jsonb(l)::text,'' ORDER BY id),''))
    INTO after_lexemes FROM public.lexemes l WHERE NOT (id=ANY(planned_ids));
  IF before_users IS DISTINCT FROM after_users OR before_lexemes IS DISTINCT FROM after_lexemes THEN
    RAISE EXCEPTION 'reading_pair_changed_preserved_state';
  END IF;
END $reading_pair$;
COMMIT;
